import{createReusableAnimation}from'../gym-frame-allocation/animation.mjs';
import{ENVIRONMENT}from'./environment-registration.mjs';
import{lighting}from'./selected-environment-core.mjs';
import{GYM12}from'./registration.mjs';
const own=(o,k)=>Object.hasOwn(o,k),dirs=['up','down','left','right'];
const digest=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),v=>v.toString(16).padStart(2,'0')).join('');
const supportLeases=new WeakMap;
export async function loadGym12Provider(no,{signal,presentation=true,supportLeaseToken=null}={}){
 const r=GYM12[no];if(!r)throw Error('GYM12_NUMBER');let disposed=false,hasDraw=false,issuedFrame=null,issuedToken=null;const borrowed=supportLeaseToken!==null;let bank;if(borrowed){bank=supportLeases.get(supportLeaseToken);if(!presentation||!bank||!bank.ownerOpen||!bank.ready||bank.registration!==r||bank.gym!==no)throw Error('GYM12_SUPPORT_LEASE_REJECTED');bank.refs++}else bank={registration:r,gym:no,masks:new Map,refs:1,ownerOpen:true,ready:false};const masks=bank.masks,images=new Map;let leaseToken=null;let sourcePixels=null,lastState=null,animate=null,animationFrame=null;let water,leaves,restoreCanvas=null,restoreContext=null;const foreground=[];let background=null,bg=null;
 async function bytes(file,hash){const res=await fetch(new URL(file,import.meta.url),{signal});if(!res.ok)throw Error('GYM12_RESOURCE_HTTP');const b=await res.arrayBuffer();if(await digest(b)!==hash)throw Error('GYM12_PIN_MISMATCH');return b}
 async function bitmap(pin){if(images.has(pin.file))return;const b=await bytes(pin.file,pin.sha256);const im=await createImageBitmap(new Blob([b],{type:'image/png'}));images.set(pin.file,im)}
 const dispose=()=>{if(disposed)return;disposed=true;if(!borrowed)bank.ownerOpen=false;if(--bank.refs===0)bank.masks.clear();let first;for(const im of images.values())try{im.close()}catch(e){first??=e}images.clear();issuedFrame=null;issuedToken=null;hasDraw=false;for(const f of foreground){f.mask.width=f.mask.height=1}foreground.length=0;if(restoreCanvas)restoreCanvas.width=restoreCanvas.height=1;restoreCanvas=restoreContext=null;sourcePixels=animate=animationFrame=water=leaves=null;if(background)background.width=background.height=1;signal?.removeEventListener('abort',dispose);if(first)throw first};
 try{if(signal?.aborted)throw Error('GYM12_ABORTED');if(presentation){background=new OffscreenCanvas(...r.size);bg=background.getContext('2d')}if(presentation)await bitmap(r.image);for(const [state,p]of Object.entries(r.states)){if(!borrowed){const rows=JSON.parse(new TextDecoder().decode(await bytes(p.maskFile,p.maskSHA))),mask=new Uint8Array(r.size[0]*r.size[1]);for(const[y,a,b]of rows)mask.fill(1,y*r.size[0]+a,y*r.size[0]+b);masks.set(+state,mask);}if(presentation)for(const patch of p.patches)await bitmap(patch)}if(presentation){for(const f of r.foreground)await bitmap(f);water=new Uint32Array(await bytes(ENVIRONMENT[no].water.file,ENVIRONMENT[no].water.sha256));leaves=new Uint32Array(await bytes(ENVIRONMENT[no].leaves.file,ENVIRONMENT[no].leaves.sha256));}if(presentation){const scan=new OffscreenCanvas(...r.size),sq=scan.getContext('2d');let maxW=1,maxH=1;for(const pin of r.foreground){sq.clearRect(0,0,...r.size);sq.drawImage(images.get(pin.file),0,0);const raw=sq.getImageData(0,0,...r.size).data;let x0=r.size[0],y0=r.size[1],x1=-1,y1=-1;for(let y=0;y<r.size[1];y++)for(let x=0;x<r.size[0];x++)if(raw[(y*r.size[0]+x)*4+3]){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y)}if(x1<0)continue;const w=x1-x0+1,h=y1-y0+1,mask=new OffscreenCanvas(w,h),mq=mask.getContext('2d'),binary=mq.createImageData(w,h);for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(raw[((y+y0)*r.size[0]+x+x0)*4+3])binary.data[(y*w+x)*4+3]=255;mq.putImageData(binary,0,0);foreground.push({baseY:pin.baseY,x:x0,y:y0,w,h,mask,binary:binary.data});images.get(pin.file).close();images.delete(pin.file);maxW=Math.max(maxW,w);maxH=Math.max(maxH,h)}scan.width=scan.height=1;restoreCanvas=new OffscreenCanvas(maxW,maxH);restoreContext=restoreCanvas.getContext('2d');animate=createReusableAnimation(water,leaves,...r.size);}if(signal?.aborted)throw Error('GYM12_ABORTED');signal?.addEventListener('abort',dispose,{once:true});bank.ready=true;if(!presentation){leaseToken=Object.freeze({});supportLeases.set(leaseToken,bank)}}catch(e){dispose();throw e}
 const safe=(foot,state)=>!disposed&&masks.has(state)&&Array.isArray(foot)&&Object.getPrototypeOf(foot)===Array.prototype&&Reflect.ownKeys(foot).length===3&&foot.length===2&&['0','1'].every(k=>{const d=Object.getOwnPropertyDescriptor(foot,k);return d?.enumerable&&Object.hasOwn(d,'value')&&Number.isSafeInteger(d.value)})&&foot[0]>=0&&foot[1]>=0&&foot[0]<r.size[0]&&foot[1]<r.size[1]&&masks.get(state)[foot[1]*r.size[0]+foot[0]]===1;
 const describe=(foot,facing,state)=>{if(!safe(foot,state)||!dirs.includes(facing))throw Error('GYM12_POSE_SUPPORT');return {version:1,sceneId:r.sceneId,mapId:r.mapId,revision:r.revision,imageSHA:r.image.sha256,maskSHA:r.states[state].maskSHA,foot:[...foot],facing,state}};
 const validate=p=>{try{const keys=['version','sceneId','mapId','revision','imageSHA','maskSHA','foot','facing','state'];if(!p||Object.getPrototypeOf(p)!==Object.prototype||Reflect.ownKeys(p).length!==keys.length)return false;const values={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(p,k);if(!d?.enumerable||!own(d,'value'))return false;values[k]=d.value}const expected=describe(values.foot,values.facing,values.state);return ['version','sceneId','mapId','revision','imageSHA','maskSHA','facing','state'].every(k=>values[k]===expected[k])&&values.foot[0]===expected.foot[0]&&values.foot[1]===expected.foot[1]}catch{return false}};
 const draw=(ctx,camera,state,{timeMs=0,nightMix=0,waterOn=true,leafOn=true}={})=>{issuedFrame=null;issuedToken=null;hasDraw=false;if(disposed||!presentation||!r.states[state])return false;if(!Number.isFinite(timeMs)||!Number.isFinite(nightMix)||nightMix<0||nightMix>1)throw Error('GYM12_ENVIRONMENT_CLOCK');if(lastState!==state){bg.clearRect(0,0,...r.size);bg.drawImage(images.get(r.image.file),0,0);for(const p of r.states[state].patches)bg.drawImage(images.get(p.file),...p.xy);sourcePixels=bg.getImageData(0,0,...r.size).data;lastState=state;}const{pixels}=animate(sourcePixels,timeMs,{waterOn,leafOn});if(!animationFrame)animationFrame=new ImageData(pixels,...r.size);if(animationFrame.data!==pixels)animationFrame.data.set(pixels);bg.putImageData(animationFrame,0,0);lighting(bg,ENVIRONMENT[no].row,nightMix);ctx.drawImage(background,-(camera?.x??0),-(camera?.y??0));hasDraw=true;return true};
 const currentFrame=()=>{if(disposed||!presentation||!hasDraw)throw Error('GYM12_PRESENTATION_UNAVAILABLE');issuedToken=null;issuedFrame=bg.getImageData(0,0,...r.size);return issuedFrame};
 const currentFrameToken=()=>{if(disposed||!presentation||!hasDraw)throw Error('GYM12_PRESENTATION_UNAVAILABLE');issuedFrame=null;issuedToken=Object.freeze({});return issuedToken};
 // Load-time binary masks; private CURRENT lit background canvas. No actor RGBA readback/copy.
 const restoreForegroundToken=(ctx,frame,actorFoot)=>{if(disposed||!presentation)return false;if(!hasDraw||!frame||frame!==issuedToken)throw Error('GYM12_CURRENT_FRAME_PROVENANCE');if(frame===issuedFrame&&(frame.width!==r.size[0]||frame.height!==r.size[1])||ctx.canvas.width!==r.size[0]||ctx.canvas.height!==r.size[1])throw Error('GYM12_FOREGROUND_NATIVE_FRAME');if(!Array.isArray(actorFoot)||actorFoot.length!==2||!actorFoot.every(Number.isFinite))throw Error('GYM12_FOREGROUND_FOOT');ctx.save();try{ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;ctx.imageSmoothingEnabled=false;ctx.shadowColor='rgba(0,0,0,0)';ctx.shadowBlur=0;ctx.shadowOffsetX=ctx.shadowOffsetY=0;if('filter'in ctx)ctx.filter='none';for(const f of foreground)if(actorFoot[1]<=f.baseY){restoreContext.globalCompositeOperation='source-over';restoreContext.clearRect(0,0,restoreCanvas.width,restoreCanvas.height);restoreContext.drawImage(background,f.x,f.y,f.w,f.h,0,0,f.w,f.h);restoreContext.globalCompositeOperation='destination-in';restoreContext.drawImage(f.mask,0,0);restoreContext.globalCompositeOperation='source-over';ctx.globalCompositeOperation='destination-out';ctx.drawImage(f.mask,f.x,f.y);ctx.globalCompositeOperation='source-over';ctx.drawImage(restoreCanvas,0,0,f.w,f.h,f.x,f.y,f.w,f.h)}}finally{ctx.restore()}return true};
 const restoreForeground=(ctx,frame,actorFoot)=>{if(disposed||!presentation)return false;if(!hasDraw||!frame||frame!==issuedFrame)throw Error('GYM12_CURRENT_FRAME_PROVENANCE');if(frame.width!==r.size[0]||frame.height!==r.size[1]||ctx.canvas.width!==r.size[0]||ctx.canvas.height!==r.size[1])throw Error('GYM12_FOREGROUND_NATIVE_FRAME');for(const f of foreground)if(actorFoot[1]<=f.baseY){const source=bg.getImageData(f.x,f.y,f.w,f.h),out=ctx.getImageData(f.x,f.y,f.w,f.h);for(let i=0;i<f.binary.length;i+=4)if(f.binary[i+3])out.data.set(source.data.subarray(i,i+4),i);ctx.putImageData(out,f.x,f.y)}return true};
 return Object.freeze({registration:r,get pinsVerified(){return !disposed},leaseToken,get supportLeaseStats(){return Object.freeze({references:bank.refs,ownerOpen:bank.ownerOpen,retainedMaskBytes:bank.masks.size*r.size[0]*r.size[1]})},safe,describe,validate,draw,currentFrame,currentFrameToken,restoreForeground,restoreForegroundToken,dispose});
}

export const loadGym12Support=(no,options={})=>loadGym12Provider(no,{...options,presentation:false});
